function deriveFieldNationPay(job, decision) {
    const estimatedHours = Math.max(1, Math.round((job.compensation.estimatedHours ?? job.requestedWindow.durationHours) * 100) /
        100);
    if (job.compensation.payType === "hourly") {
        return {
            payType: "hourly",
            baseUnits: estimatedHours,
            baseAmount: decision.counterOffer?.hourlyRate ??
                job.compensation.hourlyRate ??
                0
        };
    }
    return {
        payType: "fixed",
        baseUnits: estimatedHours,
        baseAmount: decision.counterOffer?.totalAmount ??
            job.compensation.totalBudget
    };
}
export function buildFieldNationRequest(job, decision) {
    const workOrderId = job.platformWorkOrderId ?? job.id.replace(/^fn:/, "");
    if (!decision.executionPlan) {
        throw new Error("Decision is missing execution plan");
    }
    if (decision.executionPlan.action === "apply") {
        return {
            platform: "FieldNation",
            action: "apply",
            method: "POST",
            path: `/v2/workorders/${workOrderId}/requests?acting_user_id=<user-id>&clientPayTermsAccepted=true`,
            contentType: "application/json",
            body: {
                work_order_id: workOrderId,
                eta: {
                    start: {
                        local: job.requestedWindow.earliestStart
                    },
                    hour_estimate: job.compensation.estimatedHours ?? job.requestedWindow.durationHours
                }
            },
            auth: {
                requiresCookies: true,
                requiresCsrfToken: false
            }
        };
    }
    if (decision.executionPlan.action === "counter") {
        const pay = deriveFieldNationPay(job, decision);
        const body = {
            technician: { id: "<user-id>" },
            counter: true,
            active: true,
            expiryTime: 0,
            expenses: [],
            notes: decision.counterOffer?.note ??
                "Counter offer generated by FieldOps v2",
            pay: {
                type: pay.payType,
                base: {
                    units: pay.baseUnits,
                    amount: pay.baseAmount
                },
                additional: {
                    units: 0,
                    amount: 0
                }
            }
        };
        if ((decision.counterOffer?.travelExpense ?? 0) > 0) {
            body.expenses.push({
                description: "travel",
                amount: decision.counterOffer?.travelExpense,
                quantity: 1,
                category: {
                    uid: 2,
                    id: 2
                }
            });
        }
        if (decision.counterOffer?.counterStart) {
            body.eta = {
                start: {
                    local: decision.counterOffer.counterStart
                },
                hour_estimate: job.compensation.estimatedHours ?? job.requestedWindow.durationHours
            };
        }
        return {
            platform: "FieldNation",
            action: "counter",
            method: "POST",
            path: `/v2/workorders/${workOrderId}/requests?acting_user_id=<user-id>&clientPayTermsAccepted=true`,
            contentType: "application/json",
            body,
            auth: {
                requiresCookies: true,
                requiresCsrfToken: false
            }
        };
    }
    throw new Error(`Unsupported FieldNation execution action: ${decision.executionPlan.action}`);
}
